#!/usr/bin/env python3
"""Summarize all fixed V8 signed measurements, rejecting dropped/changed samples."""
from pathlib import Path
import json,statistics
ROOT=Path(__file__).resolve().parents[1];run=ROOT/'bench/results/signed-v8-quiescent';p=json.load(open(run/'raw.json'));diag=json.load(open(ROOT/'bench/results/signed-v8-fixture-check/raw.json'));by={w['name']:w for w in diag['workloads']};assert len(p['workloads'])==10 and not p['diagnostic']
lines=['# V8 signed-decomposition baseline and generalizations','','All10 fixed workloads completed nine fresh-process timings and three separate RSS measurements: **120/120 VERIFIED**. All physical artifacts match the earlier diagnostic run byte-for-byte. This establishes a baseline for the new rule, not an optimization speedup. No failed sample was discarded.','','The fixed matrix combines three sizes (1,16,512) and capacities0,2/7,212 with renamed and permuted input/output variables and rows, affine flow shifts/scales, complemented binary activations, rational costs and nonzero objective constants. Full mapped domains, rows, objective and all flow/activation observations are checked. The tenth workload is the unchanged complete actual27 certificate. These nine serialized variants add generalization evidence to72 independent Fraction cases and six joint batches.','','All three case workers held computation during the measurement. The78preparer was paused and resumed without losing progress; its receipt separately discloses that pause. The root checkpoint had finished before timing began. OS and unrelated app activity remain uncontrolled. Warm files, no cache flushing, fresh process for every sample. Source is the frozen `audit/checkpoints/v8-source`, locked release build, rustc1.96.0, AppleM5/10cores/16GiB, macOS26.6.2. Raw files retain exact hardware, source, lock, binary and artifact hashes. Diagnostic run timings overlapped other work and are excluded.','','```sh','python3 tools/benchmark_signed.py --kernel target/validation-checkpoint-v8/release/rpx --source-root audit/checkpoints/v8-source --label signed-v8-quiescent','python3 tools/report_signed.py','```','','Use a new label to repeat; existing evidence is never overwritten. Times below are min/median/max in milliseconds. Process includes startup, read/decode/check, verification, output and shutdown; execution is the CLI verification phase. RSS is median peak resident size from three separate processes.','','| Workload | RPA/RPX bytes | Execute ms | Process ms | RSS MiB |','|---|---:|---:|---:|---:|']
def dist(vals):return '/'.join(f'{x:.3f}' for x in [min(vals),statistics.median(vals),max(vals)])
for w in p['workloads']:
 assert len(w['samples'])==9 and len(w['rss'])==3 and w['all_verified'];assert w['artifacts']==by[w['name']]['artifacts']
 s=w['samples'][0]['result']['statistics']
 assert all(x['exit_code']==0 and x['result']['status']=='VERIFIED' and x['result']['statistics']==s for x in w['samples'])
 assert all(x['exit_code']==0 and json.loads(x['stdout'])['status']=='VERIFIED' and json.loads(x['stdout'])['statistics']==s for x in w['rss'])
 exe=[x['result']['execute_us']/1000 for x in w['samples']];proc=[x['wall_ns']/1e6 for x in w['samples']]
 assert w['summary']['execute_ms']==dict(zip(['min','median','max'],[min(exe),statistics.median(exe),max(exe)]));assert w['summary']['process_ms']==dict(zip(['min','median','max'],[min(proc),statistics.median(proc),max(proc)]))
 lines.append(f"| {w['name']} | {w['artifacts']['proof.rpa']['bytes']}/{w['artifacts']['proof.rpx']['bytes']} | {dist(exe)} | {dist(proc)} | {statistics.median(x['bytes'] for x in w['rss'])/2**20:.3f} |")
lines += ['','| Workload | Read/model/proof decode ms medians | Obligations | Linear/substitution terms | Work | Generated vars/rows |','|---|---:|---:|---:|---:|---:|']
for w in p['workloads']:
 s=w['samples'][0]['result']['statistics'];med=lambda k:statistics.median(x['result'][k] for x in w['samples'])/1000
 generated=lambda field:sum(s.get(k+'_generated_'+field,0) for k in ['signed','interval','flow','menu','injectivity'])
 lines.append(f"| {w['name']} | {med('read_us'):.3f}/{med('model_decode_us'):.3f}/{med('proof_decode_us'):.3f} | {s['obligations']} | {s['linear_terms']}/{s['substitution_terms']} | {s['work']} | {generated('variables')}/{generated('rows')} |")
lines += ['','Generation and assembly are separate single observations, not repeated verification measurements. Synthetic MCM is written directly by an independent exact Python encoder; no synthetic MPS canonicalization was performed or charged as zero. Every model is still loaded, decoded and validated by the trusted Rust path in full verification. Actual27 preparation includes its actual MPS canonicalization and is disclosed from its preserved historical receipt, which is not a controlled comparison.','','| Workload | Generate seconds | Assembly process ms |','|---|---:|---:|']
for w in p['workloads']:
 if w['name'].startswith('test'):continue
 lines.append(f"| {w['name']} | {w['generation_ns']/1e9:.6f} | {w['preparation'][0]['wall_ns']/1e6:.3f} |")
r=json.load(open(run/'receipts/test27.json'));stage={x['command'][1]:json.loads(x['stdout']) for x in r['kernel_runs']};canon=sum(json.loads(x['stdout'])['total_us'] for x in r['kernel_runs'] if x['command'][1]=='canonical')/1000
lines+=['',f"Actual27 historical RPA preparation: {r['preparation_seconds']:.3f}s; two canonicalizer internal totals {canon:.3f}ms; assembler internal total {stage['assemble']['total_us']/1000:.3f}ms. Original receipt and executable identity are retained.",'','Metered work counts sparse operations rather than CPU instructions or exact bigint complexity. Generated rows/variables are logical model size, not peak physical memory. SignedLift avoids multiplying whole-output sign branches across independent items; it does not claim compactness or linear complexity for arbitrary reformulations. Eager model/proof decoding and exact arithmetic remain costs. No changes to arithmetic, bounds, obligations or resource ceilings were made to improve this baseline.','']
(ROOT/'bench/SIGNED_V8_REPORT.md').write_text('\n'.join(lines));print('PASS:120successful processes; all distributions/statistics/artifacts checked')
